// GET /api/roster/export: the roster as CSV, one row per player.
export const quote = (field: string): string => `"${field.replaceAll('"', '""')}"`;

export function toCsv(players: { name: string; team: string }[]): string {
  const rows = players.map((p) => [p.name, p.team].map(quote).join(","));
  return ["name,team", ...rows].join("\n");
}

files.tests/export.test.ts:
import { toCsv } from "../server/api/roster/export.get";

test("a name with a comma stays in one column", () => {
  expect(toCsv([{ name: "Smith, Jo", team: "Red" }])).toBe('name,team\n"Smith, Jo","Red"');
});

